"""Typer application: ``mavctl`` command surface."""

from __future__ import annotations

from typing import Annotated, Any

import typer

from mavctl.cli.render import emit_success, fail
from mavctl.daemon import process
from mavctl.daemon.client import DaemonNotRunningError, call_daemon
from mavctl.models import ExitCode
from mavctl.paths import socket_path

app = typer.Typer(
    name="mavctl",
    help="Headless MAVLink ground control station CLI.",
    no_args_is_help=True,
    add_completion=False,
)
daemon_app = typer.Typer(help="Manage the mavctl daemon process.", no_args_is_help=True)
app.add_typer(daemon_app, name="daemon")

JsonOption = Annotated[bool, typer.Option("--json", help="Emit structured JSON to stdout.")]
ConfirmOption = Annotated[
    bool, typer.Option("--confirm", help="Confirm this state-changing command (required).")
]
DryRunOption = Annotated[
    bool, typer.Option("--dry-run", help="Run safety checks and report without executing.")
]
ForceOption = Annotated[bool, typer.Option("--force", help="Override safety checks (DANGEROUS).")]
WaitOption = Annotated[
    bool, typer.Option("--wait", help="Block until the target state is reached.")
]
TimeoutOption = Annotated[
    float, typer.Option("--timeout", help="Seconds to wait when --wait is set (default 60).")
]

_DAEMON_DOWN_HINT = "daemon is not running; start it with 'mavctl daemon start --connect <conn>'"

# Client socket timeout for quick queries; commands compute their own.
_QUERY_TIMEOUT = 5.0
# Buffer added on top of an ACK burst (retries) / a --wait window.
_COMMAND_BASE_TIMEOUT = 25.0


def _client_timeout(wait: bool, timeout: float) -> float:
    return timeout + 30.0 if wait else _COMMAND_BASE_TIMEOUT


def _call(
    method: str,
    json_mode: bool,
    params: dict[str, Any] | None = None,
    timeout: float = _QUERY_TIMEOUT,
) -> dict[str, Any]:
    """Call a daemon method, mapping failures to the exit-code contract."""

    try:
        response = call_daemon(method, params, timeout=timeout)
    except DaemonNotRunningError:
        fail(ExitCode.DAEMON_NOT_RUNNING, _DAEMON_DOWN_HINT, json_mode=json_mode)
    except (OSError, ValueError) as exc:
        fail(ExitCode.GENERAL_ERROR, f"daemon communication failed: {exc}", json_mode=json_mode)

    if not response.ok:
        err = response.error
        assert err is not None  # ok is False -> error is populated
        message = err.message
        hint = err.detail.get("hint")
        if hint and not json_mode:
            message = f"{message}\nhint: {hint}"
        fail(err.code, message, json_mode=json_mode, detail=err.detail)
    return response.result or {}



# -- daemon subcommands ----------------------------------------------------


@daemon_app.command("start")
def daemon_start(
    connect: Annotated[
        str, typer.Option("--connect", help="mavutil connection string, e.g. udp:127.0.0.1:14550")
    ],
    heartbeat_timeout: Annotated[
        float, typer.Option("--heartbeat-timeout", help="Seconds before link is deemed lost.")
    ] = 3.0,
    json_mode: JsonOption = False,
) -> None:
    """Start the background daemon and connect to the vehicle."""

    if process.is_running():
        pid = process.read_pid()
        emit_success(
            {"status": "already_running", "pid": pid},
            json_mode=json_mode,
            human=f"daemon already running (pid {pid})",
        )
        return

    try:
        pid = process.spawn(connect, heartbeat_timeout)
    except RuntimeError as exc:
        fail(ExitCode.GENERAL_ERROR, str(exc), json_mode=json_mode)

    emit_success(
        {"status": "started", "pid": pid, "connection_string": connect},
        json_mode=json_mode,
        human=f"daemon started (pid {pid}), connecting to {connect}",
    )


@daemon_app.command("stop")
def daemon_stop(json_mode: JsonOption = False) -> None:
    """Stop the running daemon."""

    if not process.is_running():
        fail(ExitCode.DAEMON_NOT_RUNNING, "daemon is not running", json_mode=json_mode)

    stopped = process.stop()
    emit_success(
        {"status": "stopped" if stopped else "not_running"},
        json_mode=json_mode,
        human="daemon stopped" if stopped else "daemon was not running",
    )


@daemon_app.command("status")
def daemon_status(json_mode: JsonOption = False) -> None:
    """Report whether the daemon is running (exit 3 if not)."""

    running = process.is_running()
    pid = process.read_pid() if running else None
    data = {"running": running, "pid": pid, "socket": str(socket_path())}
    if not running:
        fail(
            ExitCode.DAEMON_NOT_RUNNING,
            "daemon is not running",
            json_mode=json_mode,
            detail=data,
        )
    emit_success(data, json_mode=json_mode, human=f"daemon running (pid {pid})")


# -- top-level commands ----------------------------------------------------


@app.command("status")
def status(json_mode: JsonOption = False) -> None:
    """Show vehicle connection status, flight mode, arming, power, GPS."""

    state = _call("status", json_mode)
    emit_success(state, json_mode=json_mode, human=_format_state(state))


@app.command("telemetry")
def telemetry(json_mode: JsonOption = False) -> None:
    """Show a position / attitude / velocity snapshot."""

    snapshot = _call("telemetry", json_mode)
    emit_success(snapshot, json_mode=json_mode, human=_format_telemetry(snapshot))


# -- flight-control commands -----------------------------------------------


@app.command("arm")
def arm(
    confirm: ConfirmOption = False,
    force: ForceOption = False,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Arm the vehicle (requires --confirm)."""

    result = _call(
        "arm",
        json_mode,
        {"confirm": confirm, "force": force, "dry_run": dry_run},
        timeout=_COMMAND_BASE_TIMEOUT,
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))


@app.command("disarm")
def disarm(
    confirm: ConfirmOption = False,
    force: ForceOption = False,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Disarm the vehicle (requires --confirm; --force to override in-flight)."""

    result = _call(
        "disarm",
        json_mode,
        {"confirm": confirm, "force": force, "dry_run": dry_run},
        timeout=_COMMAND_BASE_TIMEOUT,
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))


@app.command("mode")
def mode(
    mode_name: Annotated[
        str, typer.Argument(metavar="MODE", help="Target flight mode, e.g. GUIDED")
    ],
    confirm: ConfirmOption = False,
    wait: WaitOption = False,
    timeout: TimeoutOption = 60.0,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Switch flight mode (requires --confirm)."""

    result = _call(
        "mode",
        json_mode,
        {
            "mode": mode_name,
            "confirm": confirm,
            "wait": wait,
            "timeout": timeout,
            "dry_run": dry_run,
        },
        timeout=_client_timeout(wait, timeout),
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))


@app.command("takeoff")
def takeoff(
    alt: Annotated[float, typer.Option("--alt", help="Target relative altitude in metres.")],
    confirm: ConfirmOption = False,
    wait: WaitOption = False,
    timeout: TimeoutOption = 60.0,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Take off to a target altitude (requires --confirm; GUIDED + armed)."""

    result = _call(
        "takeoff",
        json_mode,
        {"alt": alt, "confirm": confirm, "wait": wait, "timeout": timeout, "dry_run": dry_run},
        timeout=_client_timeout(wait, timeout),
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))


@app.command("land")
def land(
    confirm: ConfirmOption = False,
    wait: WaitOption = False,
    timeout: TimeoutOption = 60.0,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Land at the current position (requires --confirm)."""

    result = _call(
        "land",
        json_mode,
        {"confirm": confirm, "wait": wait, "timeout": timeout, "dry_run": dry_run},
        timeout=_client_timeout(wait, timeout),
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))


@app.command("rtl")
def rtl(
    confirm: ConfirmOption = False,
    wait: WaitOption = False,
    timeout: TimeoutOption = 60.0,
    dry_run: DryRunOption = False,
    json_mode: JsonOption = False,
) -> None:
    """Return to launch (requires --confirm)."""

    result = _call(
        "rtl",
        json_mode,
        {"confirm": confirm, "wait": wait, "timeout": timeout, "dry_run": dry_run},
        timeout=_client_timeout(wait, timeout),
    )
    emit_success(result, json_mode=json_mode, human=_format_command(result))



# -- human formatters ------------------------------------------------------


def _fmt(value: Any, suffix: str = "", nd: int = 2) -> str:
    if value is None:
        return "n/a"
    if isinstance(value, float):
        return f"{value:.{nd}f}{suffix}"
    return f"{value}{suffix}"


def _format_state(s: dict[str, Any]) -> str:
    battery = s.get("battery") or {}
    gps = s.get("gps") or {}
    connected = s.get("connected")
    lines = [
        f"connection : {'CONNECTED' if connected else 'DISCONNECTED'} "
        f"({s.get('connection_string') or 'n/a'})",
        f"heartbeat  : {_fmt(s.get('heartbeat_age_s'), 's')} ago"
        f"  sys={_fmt(s.get('system_id'))} comp={_fmt(s.get('component_id'))}",
        f"mode       : {s.get('flight_mode') or 'n/a'}",
        f"armed      : {'ARMED' if s.get('armed') else 'disarmed' if connected else 'n/a'}",
        f"status     : {s.get('system_status') or 'n/a'}"
        f"  landed={s.get('landed_state') or 'n/a'}"
        f"  rel_alt={_fmt(s.get('relative_alt_m'), ' m')}",
        f"battery    : {_fmt(battery.get('voltage_v'), ' V')}"
        f"  {_fmt(battery.get('current_a'), ' A')}"
        f"  {_fmt(battery.get('remaining_pct'), ' %', nd=0)}",
        f"gps        : {gps.get('fix_label') or 'n/a'}"
        f"  sats={_fmt(gps.get('satellites_visible'))}",
    ]
    home = s.get("home_position")
    if home:
        lines.append(
            f"home       : lat={_fmt(home.get('lat_deg'), nd=7)}"
            f"  lon={_fmt(home.get('lon_deg'), nd=7)}"
            f"  alt_msl={_fmt(home.get('alt_msl_m'), ' m')}"
        )
    return "\n".join(lines)


def _format_command(r: dict[str, Any]) -> str:
    action = r.get("action", "command")
    if r.get("dry_run"):
        verdict = "WOULD EXECUTE" if r.get("would_execute") else "no-op (already satisfied)"
        lines = [f"[dry-run] {action}: {verdict}"]
        if r.get("note"):
            lines.append(f"  note: {r.get('note')}")
        for c in r.get("checks", []):
            mark = "PASS" if c.get("passed") else "FAIL"
            lines.append(f"  [{mark}] {c.get('name')}: {c.get('detail')}")
        return "\n".join(lines)
    if r.get("already_satisfied"):
        return f"{action}: already satisfied ({r.get('note')}) — no action taken"
    outcome = r.get("outcome") or {}
    parts = [f"{action}: {outcome.get('result_name', 'OK')}"]
    if r.get("waited") is True:
        parts.append("(target state reached)")
    if r.get("note"):
        parts.append(f"— note: {r.get('note')}")
    return " ".join(parts)



def _format_telemetry(t: dict[str, Any]) -> str:
    pos = t.get("position") or {}
    att = t.get("attitude") or {}
    vel = t.get("velocity") or {}
    lines = [
        f"position : lat={_fmt(pos.get('lat_deg'), nd=7)}  lon={_fmt(pos.get('lon_deg'), nd=7)}",
        f"           alt_msl={_fmt(pos.get('alt_msl_m'), ' m')}"
        f"  rel_alt={_fmt(pos.get('relative_alt_m'), ' m')}",
        f"attitude : roll={_fmt(att.get('roll_deg'), ' deg')}"
        f"  pitch={_fmt(att.get('pitch_deg'), ' deg')}"
        f"  yaw={_fmt(att.get('yaw_deg'), ' deg')}",
        f"velocity : gs={_fmt(vel.get('groundspeed_ms'), ' m/s')}"
        f"  hdg={_fmt(vel.get('heading_deg'), ' deg')}"
        f"  vz={_fmt(vel.get('vz_ms'), ' m/s')}",
    ]
    return "\n".join(lines)


def main() -> None:
    """Console-script entrypoint."""

    app()


if __name__ == "__main__":
    main()

"""Asyncio Unix-socket server that owns the vehicle link and answers RPCs."""

from __future__ import annotations

import asyncio
import contextlib
import signal
from collections.abc import Awaitable, Callable
from typing import Any

from mavctl.adapter.base import AdapterError, VehicleAdapter
from mavctl.daemon import guards, wire
from mavctl.daemon.guards import GuardConfig, GuardDecision
from mavctl.models import CommandOutcome, DaemonResponse, ExitCode, RpcRequest, WaitStatus
from mavctl.paths import runtime_dir, socket_path

# Max bytes accepted for a single request frame (defensive bound).
_MAX_FRAME = 64 * 1024

# Default --wait timeout in seconds when the client does not specify one.
_DEFAULT_WAIT_TIMEOUT = 60.0

# Fraction of target altitude that counts as "takeoff reached".
_TAKEOFF_REACHED_FRACTION = 0.95

# Poll interval while --wait is active.
_WAIT_POLL_INTERVAL = 0.25

Handler = Callable[[RpcRequest], Awaitable[DaemonResponse]]


class DaemonServer:
    """Serves RPC requests over a Unix socket, backed by a vehicle adapter.

    The adapter maintains the live MAVLink snapshot on its own reader thread;
    fast handlers (ping/status/telemetry) only read that snapshot, while
    command handlers run the blocking adapter verbs in an executor so the
    event loop stays responsive.
    """

    def __init__(
        self,
        adapter: VehicleAdapter,
        connection_string: str,
        guard_config: GuardConfig | None = None,
    ) -> None:
        self._adapter = adapter
        self._connection_string = connection_string
        self._guard_config = guard_config or GuardConfig()
        self._stop_event = asyncio.Event()
        self._server: asyncio.AbstractServer | None = None
        # Serializes state-changing commands end-to-end (state read -> guard ->
        # execute -> --wait) so they never interleave (TOCTOU) and no other
        # state-changing command runs during a takeoff/land wait. Fast handlers
        # (ping/status/telemetry) do NOT take this lock and stay concurrent.
        self._command_lock = asyncio.Lock()
        self._methods: dict[str, Handler] = {
            "ping": self._m_ping,
            "status": self._m_status,
            "telemetry": self._m_telemetry,
            "shutdown": self._m_shutdown,
            "arm": self._m_arm,
            "disarm": self._m_disarm,
            "mode": self._m_mode,
            "takeoff": self._m_takeoff,
            "land": self._m_land,
            "rtl": self._m_rtl,
        }

    async def serve(self) -> None:
        """Open the link, bind the socket, and serve until asked to stop."""

        self._adapter.connect()
        runtime_dir().mkdir(parents=True, exist_ok=True)
        sock = socket_path()
        with contextlib.suppress(FileNotFoundError):
            sock.unlink()

        self._install_signal_handlers()
        self._server = await asyncio.start_unix_server(self._handle_client, path=str(sock))
        try:
            await self._stop_event.wait()
        finally:
            await self._shutdown()

    def request_stop(self) -> None:
        """Signal the serve loop to unwind (safe to call from a signal handler)."""

        self._stop_event.set()

    # -- connection handling ----------------------------------------------

    async def _handle_client(
        self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter
    ) -> None:
        try:
            line = await reader.readline()
            if not line or len(line) > _MAX_FRAME:
                return
            response = await self._dispatch(line)
            writer.write(wire.encode(response.model_dump()))
            await writer.drain()
        except (ConnectionError, asyncio.IncompleteReadError):
            return
        finally:
            writer.close()
            with contextlib.suppress(ConnectionError, asyncio.CancelledError):
                await writer.wait_closed()

    async def _dispatch(self, line: bytes) -> DaemonResponse:
        try:
            request = RpcRequest.model_validate(wire.decode(line))
        except (ValueError, TypeError) as exc:
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, f"malformed request: {exc}")

        handler = self._methods.get(request.method)
        if handler is None:
            return DaemonResponse.failure(
                ExitCode.GENERAL_ERROR, f"unknown method: {request.method!r}"
            )
        try:
            return await handler(request)
        except Exception as exc:
            return DaemonResponse.failure(ExitCode.GENERAL_ERROR, f"internal error: {exc}")

    # -- fast RPC methods --------------------------------------------------

    async def _m_ping(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(
            {"pong": True, "connection_string": self._connection_string}
        )

    async def _m_status(self, _request: RpcRequest) -> DaemonResponse:
        return DaemonResponse.success(self._adapter.get_state().model_dump())

    async def _m_telemetry(self, _request: RpcRequest) -> DaemonResponse:
        state = self._adapter.get_state()
        if not state.connected:
            return self._not_connected()
        return DaemonResponse.success(self._adapter.get_telemetry().model_dump())

    async def _m_shutdown(self, _request: RpcRequest) -> DaemonResponse:
        self.request_stop()
        return DaemonResponse.success({"stopping": True})

    # -- command RPC methods ----------------------------------------------
    #
    # Every state-changing command runs its whole body under ``_command_lock``:
    # the latest-state read, the guard evaluation, the dry-run/idempotent
    # decision, the adapter call, and any --wait are one serial transaction.
    # This prevents TOCTOU races and keeps other state-changing commands out
    # during a takeoff/land wait. status/telemetry never take this lock.

    async def _m_arm(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        async with self._command_lock:
            state = self._adapter.get_state()
            if not state.connected:
                return self._not_connected()
            decision = guards.check_arm(
                state, confirm=_flag(p, "confirm"), config=self._guard_config
            )
            pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
            if pre is not None:
                return pre
            outcome = await self._blocking(self._adapter.arm, _flag(p, "force"))
            return self._command_result("arm", outcome)

    async def _m_disarm(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        async with self._command_lock:
            state = self._adapter.get_state()
            if not state.connected:
                return self._not_connected()
            decision = guards.check_disarm(
                state,
                confirm=_flag(p, "confirm"),
                force=_flag(p, "force"),
                config=self._guard_config,
            )
            pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
            if pre is not None:
                return pre
            outcome = await self._blocking(self._adapter.disarm, _flag(p, "force"))
            return self._command_result("disarm", outcome)

    async def _m_mode(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        mode = str(p.get("mode", "")).upper()
        async with self._command_lock:
            state = self._adapter.get_state()
            if not state.connected:
                return self._not_connected()
            decision = guards.check_mode(
                state,
                mode,
                self._adapter.mode_names(),
                confirm=_flag(p, "confirm"),
                config=self._guard_config,
            )
            pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
            if pre is not None:
                return pre
            outcome = await self._blocking(self._adapter.set_mode, mode)
            if not outcome.accepted:
                return self._command_result("mode", outcome)
            status = await self._maybe_wait(
                p, lambda: self._adapter.get_state().flight_mode == mode
            )
            return self._finish_wait("mode", outcome, p, status, f"mode did not switch to {mode}")

    async def _m_takeoff(self, request: RpcRequest) -> DaemonResponse:
        p = request.params
        alt_raw = p.get("alt")
        if alt_raw is None:
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, "takeoff requires numeric --alt")
        try:
            alt = float(alt_raw)
        except (TypeError, ValueError):
            return DaemonResponse.failure(ExitCode.USAGE_ERROR, "takeoff requires numeric --alt")
        async with self._command_lock:
            state = self._adapter.get_state()
            if not state.connected:
                return self._not_connected()
            decision = guards.check_takeoff(
                state, alt, confirm=_flag(p, "confirm"), config=self._guard_config
            )
            pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
            if pre is not None:
                return pre
            outcome = await self._blocking(self._adapter.takeoff, alt)
            if not outcome.accepted:
                return self._command_result("takeoff", outcome)
            target = alt * _TAKEOFF_REACHED_FRACTION
            status = await self._maybe_wait(p, lambda: self._reached_altitude(target))
            return self._finish_wait(
                "takeoff", outcome, p, status, f"altitude {target:.1f}m not reached"
            )

    async def _m_land(self, request: RpcRequest) -> DaemonResponse:
        return await self._m_descent(request, "land", self._adapter.land)

    async def _m_rtl(self, request: RpcRequest) -> DaemonResponse:
        return await self._m_descent(request, "rtl", self._adapter.rtl)

    async def _m_descent(
        self, request: RpcRequest, action: str, verb: Callable[[], CommandOutcome]
    ) -> DaemonResponse:
        p = request.params
        async with self._command_lock:
            state = self._adapter.get_state()
            if not state.connected:
                return self._not_connected()
            decision = (
                guards.check_land(state, confirm=_flag(p, "confirm"), config=self._guard_config)
                if action == "land"
                else guards.check_rtl(state, confirm=_flag(p, "confirm"), config=self._guard_config)
            )
            pre = self._pre_execute(decision, dry_run=_flag(p, "dry_run"))
            if pre is not None:
                return pre
            outcome = await self._blocking(verb)
            if not outcome.accepted:
                return self._command_result(action, outcome)
            status = await self._maybe_wait(p, lambda: self._adapter.get_state().armed is False)
            return self._finish_wait(action, outcome, p, status, "vehicle did not disarm")

    # -- helpers -----------------------------------------------------------

    def _not_connected(self) -> DaemonResponse:
        return DaemonResponse.failure(
            ExitCode.VEHICLE_NOT_CONNECTED,
            "vehicle not connected (no recent heartbeat)",
            {"connection_string": self._connection_string},
        )

    def _pre_execute(self, decision: GuardDecision, *, dry_run: bool) -> DaemonResponse | None:
        """Return a terminal response for dry-run/reject/idempotent, else None."""

        checks = [c.model_dump() for c in decision.checks]
        if dry_run:
            if not decision.allowed:
                return DaemonResponse.failure(
                    decision.exit_code,
                    decision.message or "would be rejected",
                    {
                        "dry_run": True,
                        "reason": decision.reason,
                        "hint": decision.hint,
                        "checks": checks,
                    },
                )
            return DaemonResponse.success(
                {
                    "dry_run": True,
                    "action": decision.action,
                    "would_execute": not decision.already_satisfied,
                    "already_satisfied": decision.already_satisfied,
                    "note": decision.note,
                    "checks": checks,
                }
            )
        if not decision.allowed:
            return DaemonResponse.failure(
                decision.exit_code,
                decision.message or "rejected by safety guard",
                {"reason": decision.reason, "hint": decision.hint, "checks": checks},
            )
        if decision.already_satisfied:
            return DaemonResponse.success(
                {
                    "action": decision.action,
                    "already_satisfied": True,
                    "note": decision.note,
                    "executed": False,
                }
            )
        return None

    async def _blocking(self, fn: Callable[..., CommandOutcome], *args: Any) -> CommandOutcome:
        loop = asyncio.get_running_loop()
        try:
            return await loop.run_in_executor(None, fn, *args)
        except AdapterError as exc:
            return CommandOutcome(accepted=False, result_name=f"ADAPTER_ERROR: {exc}")

    def _command_result(
        self,
        action: str,
        outcome: CommandOutcome,
        *,
        note: str | None = None,
        waited: bool | None = None,
    ) -> DaemonResponse:
        if not outcome.accepted:
            return DaemonResponse.failure(
                ExitCode.NACK_TIMEOUT,
                f"{action} not accepted by vehicle: {outcome.result_name}",
                {"outcome": outcome.model_dump()},
            )
        result: dict[str, Any] = {
            "action": action,
            "executed": True,
            "outcome": outcome.model_dump(),
        }
        if note is not None:
            result["note"] = note
        if waited is not None:
            result["waited"] = waited
        return DaemonResponse.success(result)

    async def _maybe_wait(
        self, params: dict[str, Any], predicate: Callable[[], bool]
    ) -> WaitStatus:
        """Poll for the target state while --wait is set.

        Returns an explicit :class:`WaitStatus`. Each iteration re-checks the
        link: if the heartbeat goes stale mid-wait the command has already been
        ACKed, so we stop and report LINK_LOST (exit 4) rather than a timeout.
        """

        if not _flag(params, "wait"):
            return WaitStatus.NOT_WAITED
        timeout = _timeout(params)
        loop = asyncio.get_running_loop()
        deadline = loop.time() + timeout
        while loop.time() < deadline:
            if not self._adapter.get_state().connected:
                return WaitStatus.LINK_LOST
            if predicate():
                return WaitStatus.REACHED
            await asyncio.sleep(_WAIT_POLL_INTERVAL)
        if not self._adapter.get_state().connected:
            return WaitStatus.LINK_LOST
        return WaitStatus.REACHED if predicate() else WaitStatus.TIMEOUT

    def _finish_wait(
        self,
        action: str,
        outcome: CommandOutcome,
        params: dict[str, Any],
        status: WaitStatus,
        timeout_detail: str,
    ) -> DaemonResponse:
        """Map a --wait outcome to the response / exit-code contract."""

        if status is WaitStatus.LINK_LOST:
            return DaemonResponse.failure(
                ExitCode.VEHICLE_NOT_CONNECTED,
                f"{action} was accepted by the vehicle but the link was lost during --wait",
                {
                    "outcome": outcome.model_dump(),
                    "waited": False,
                    "reason": "link_lost_during_wait",
                },
            )
        if status is WaitStatus.TIMEOUT:
            return DaemonResponse.failure(
                ExitCode.NACK_TIMEOUT,
                f"{action} accepted but did not complete within "
                f"{_timeout(params):.0f}s: {timeout_detail}",
                {"outcome": outcome.model_dump(), "waited": False},
            )
        waited = True if status is WaitStatus.REACHED else None
        return self._command_result(action, outcome, waited=waited)

    def _reached_altitude(self, target: float) -> bool:
        rel = self._adapter.get_telemetry().position.relative_alt_m
        return rel is not None and rel >= target

    # -- teardown ----------------------------------------------------------

    def _install_signal_handlers(self) -> None:
        loop = asyncio.get_running_loop()
        for sig in (signal.SIGTERM, signal.SIGINT):
            with contextlib.suppress(NotImplementedError):
                loop.add_signal_handler(sig, self.request_stop)

    async def _shutdown(self) -> None:
        if self._server is not None:
            self._server.close()
            with contextlib.suppress(Exception):
                await self._server.wait_closed()
            self._server = None
        self._adapter.disconnect()
        with contextlib.suppress(FileNotFoundError):
            socket_path().unlink()


def _flag(params: dict[str, Any], key: str) -> bool:
    return bool(params.get(key, False))


def _timeout(params: dict[str, Any]) -> float:
    value = params.get("timeout")
    try:
        return float(value) if value is not None else _DEFAULT_WAIT_TIMEOUT
    except (TypeError, ValueError):
        return _DEFAULT_WAIT_TIMEOUT

"""Synchronous Unix-socket client used by the CLI to talk to the daemon."""

from __future__ import annotations

import socket
from typing import Any

from mavctl.daemon import wire
from mavctl.models import DaemonResponse
from mavctl.paths import socket_path


class DaemonNotRunningError(Exception):
    """Raised when no daemon is listening on the expected socket."""


def _read_frame(sock: socket.socket) -> bytes:
    chunks: list[bytes] = []
    while True:
        chunk = sock.recv(4096)
        if not chunk:
            break
        chunks.append(chunk)
        if b"\n" in chunk:
            break
    return b"".join(chunks)


def call_daemon(
    method: str,
    params: dict[str, Any] | None = None,
    timeout: float = 5.0,
) -> DaemonResponse:
    """Send one RPC request to the daemon and return its response.

    Raises:
        DaemonNotRunningError: if the socket is absent or refuses the connection.
    """

    path = socket_path()
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    try:
        try:
            sock.connect(str(path))
        except (FileNotFoundError, ConnectionRefusedError) as exc:
            raise DaemonNotRunningError(str(exc)) from exc
        sock.sendall(wire.encode({"method": method, "params": params or {}}))
        line = _read_frame(sock)
    finally:
        sock.close()

    if not line:
        raise DaemonNotRunningError("daemon closed the connection without responding")
    return DaemonResponse.model_validate(wire.decode(line))


def is_daemon_running() -> bool:
    """Return True if a daemon answers a ping on the socket."""

    try:
        return call_daemon("ping", timeout=1.0).ok
    except DaemonNotRunningError:
        return False
    except (OSError, ValueError):
        return False


class DaemonClient:
    """Thin object wrapper around :func:`call_daemon` for callers that
    prefer a handle (e.g. tests injecting a fake)."""

    def __init__(self, timeout: float = 5.0) -> None:
        self._timeout = timeout

    def call(self, method: str, params: dict[str, Any] | None = None) -> DaemonResponse:
        return call_daemon(method, params, timeout=self._timeout)

    def is_running(self) -> bool:
        return is_daemon_running()

