    for path in _DOC_FILES:
        for segment in _code_segments(path.read_text(encoding="utf-8")):
            for command in _MAVCTL_INVOCATION.findall(segment):
                assert command in _SUPPORTED_COMMANDS, f"{path.name}: mavctl {command}"

